package com.fasterxml.jackson.dataformat.xml.deser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.dataformat.xml.PackageVersion;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Set;
import javax.xml.stream.XMLStreamReader;
import javax.xml.stream.XMLStreamWriter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FromXmlParser.nextTextValue()
 */
public class FromXmlParser_nextTextValue_TriageGen2Test {

    @Mock
    private IOContext ioContext;
    @Mock
    private ObjectCodec codec;
    @Mock
    private XMLStreamReader xmlReader;
    @Mock
    private XmlXmlTokens xmlTokens; // Assuming _xmlTokens is an internal wrapper around XMLStreamReader
    @Mock
    private ParsingContext parsingContext;
    @Mock
    private ParsingContext parentContext;

    private FromXmlParser parser;

    // Internal fields access via reflection for testing complex state machines
    @SuppressWarnings("unused")
    private JsonToken _nextToken;
    @SuppressWarnings("unused")
    private JsonToken _currToken;
    @SuppressWarnings("unused")
    private String _currText;
    @SuppressWarnings("unused")
    private boolean _mayBeLeaf;
    @SuppressWarnings("unused")
    private String _cfgNameForTextElement = "text";

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);

        // We need to mock the internal _xmlTokens which is usually a wrapper
        // Since we can't easily instantiate the real internal class without a full setup, 
        // we will use reflection to inject mocks into the parser.

        parser = new FromXmlParser(ioContext, 0, 0, codec, xmlReader);

        // Inject mocks into private fields
        setField(parser, "_xmlTokens", xmlTokens);
        setField(parser, "_parsingContext", parsingContext);
        setField(parser, "_cfgNameForTextElement", "text");
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testNextTextValue_WithExistingNextToken_String() throws Exception {
        // Arrange: _nextToken is already set to VALUE_STRING
        setField(parser, "_nextToken", JsonToken.VALUE_STRING);
        setField(parser, "_currText", "hello");

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertEquals("hello", result);
        assertNull(_getPrivateField(parser, "_nextToken"));
    }

    @Test
    public void testNextTextValue_WithExistingNextToken_OtherToken() throws Exception {
        // Arrange: _nextToken is not a string
        setField(parser, "_nextToken", JsonToken.START_OBJECT);

        // Mock _updateState via spy or just assume it transitions
        FromXmlParser spyParser = spy(parser);
        doNothing().when(spyParser)._updateState(any());

        // Act
        String result = spyParser.nextTextValue();

        // Assert
        assertNull(result);
    }

    @Test
    public void testNextTextValue_XmlStartElement_MayBeLeafTrue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        setField(parser, "_mayBeLeaf", true);
        when(parsingContext.createChildObjectContext(anyInt(), anyInt())).thenReturn(parsingContext);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals(JsonToken.FIELD_NAME, _getPrivateField(parser, "_nextToken"));
        assertEquals(JsonToken.START_OBJECT, _getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlStartElement_InArray() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        setField(parser, "_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(true);
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_TEXT); // next call in loop

        // Act
        parser.nextTextValue();

        // Assert
        verify(xmlTokens, atLeast(2)).next();
    }

    @Test
    public void testNextTextValue_XmlStartElement_Normal() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        setField(parser, "_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(false);
        when(xmlTokens.getLocalName()).thenReturn("elementName");

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        verify(parsingContext).setCurrentName("elementName");
        assertEquals(JsonToken.FIELD_NAME, _getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlEndElement_MayBeLeafTrue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END_ELEMENT);
        setField(parser, "_mayBeLeaf", true);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertEquals("", result);
        assertEquals(JsonToken.VALUE_STRING, _getPrivateField(parser, "_currToken"));
        assertEquals(false, _getPrivateField(parser, "_mayBeLeaf"));
    }

    @Test
    public void testNextTextValue_XmlEndElement_NotMayBeLeaf() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END_ELEMENT);
        setField(parser, "_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(true);
        when(parsingContext.getParent()).thenReturn(parentContext);
        when(parentContext.getNamesToWrap()).thenReturn(null);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals(JsonToken.END_ARRAY, _getPrivateField(parser, "_currToken"));
        verify(parsingContext).getParent();
    }

    @Test
    public void testNextTextValue_XmlAttributeName_MayBeLeafTrue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_NAME);
        setField(parser, "_mayBeLeaf", true);
        when(xmlTokens.getText()).thenReturn("attrVal");
        when(parsingContext.createChildObjectContext(anyInt(), anyInt())).thenReturn(parsingContext);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals(JsonToken.FIELD_NAME, _getPrivateField(parser, "_nextToken"));
        assertEquals("attrVal", _getPrivateField(parser, "_currText"));
        assertEquals(JsonToken.START_OBJECT, _getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlAttributeName_Normal() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_NAME);
        setField(parser, "_mayBeLeaf", false);
        when(xmlTokens.getLocalName()).thenReturn("attrName");

        // Act
        parser.nextTextValue();

        // Assert
        verify(parsingContext).setCurrentName("attrName");
        assertEquals(JsonToken.FIELD_NAME, _getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlAttributeValue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_VALUE);
        when(xmlTokens.getText()).thenReturn("val");

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals("val", _getPrivateField(parser, "_currText"));
        assertEquals(JsonToken.VALUE_STRING, _getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlText_MayBeLeafTrue() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_TEXT);
        when(xmlTokens.getText()).thenReturn("textContent");
        setField(parser, "_mayBeLeaf", true);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertEquals("textContent", result);
        verify(xmlTokens).skipEndElement();
        assertEquals(JsonToken.VALUE_STRING, _getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlText_NotMayBeLeaf() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_TEXT);
        when(xmlTokens.getText()).thenReturn("textContent");
        setField(parser, "_mayBeLeaf", false);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        verify(parsingContext).setCurrentName("text");
        assertEquals(JsonToken.FIELD_NAME, _getPrivateField(parser, "_currToken");
        assertEquals(JsonToken.VALUE_STRING, _getPrivateField(parser, "_nextToken"));
    }

    @Test
    public void testNextTextValue_XmlEnd() throws Exception {
        // Arrange
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertNull(_getPrivateField(parser, "_currToken"));
    }

    private Object _getPrivateField(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }
}

/**
 * Dummy class to represent the internal XmlXmlTokens wrapper if not available in classpath
 * In a real scenario, this would be the actual class being used by the parser.
 */
class XmlTokenStream {
    public static final int XML_START_ELEMENT = 1;
    public static final int XML_END_ELEMENT = 2;
    public static final int XML_ATTRIBUTE_NAME = 3;
    public static final int XML_ATTRIBUTE_VALUE = 4;
    public static final int XML_TEXT = 5;
    public static final int XML_END = 6;
}

/**
 * Mocking internal interface for the test
 */
interface XmlXmlTokens {
    int next() throws IOException;
    String getLocalName() throws IOException;
    String getText() throws IOException;
    void repeatStartElement() throws IOException;
    void skipEndElement() throws IOException;
}
